package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#unsplit()
 */
public class StopWatch_unsplit_TriageGen2Test {

    @Test
    public void testUnsplit_WhenNotSplit_ThrowsIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // Ensure state is NOT STATE_SPLIT (Initial state is UNSPLIT)
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException to be thrown because stopwatch was not split.");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_WhenSplit_SuccessfullyUnsplits() {
        StopWatch stopWatch = new StopWatch();

        // Setup state to STATE_SPLIT
        stopWatch.start();
        stopWatch.split();

        // Verify it is in split state (indirectly via method execution)
        // We call unsplit() which should transition state to STATE_UNSPLIT
        stopWatch.unsplit();

        // After unsplit, calling unsplit again should throw exception (verifying state change)
        try {
            stopWatch.unsplit();
            Assert.fail("Expected IllegalStateException because stopwatch should now be UNSPLIT.");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch has not been split. ", e.getMessage());
        }
    }

    @Test
    public void testUnsplit_VerifiesStopTimeReset() {
        StopWatch stopWatch = new StopWatch();

        stopWatch.start();
        // Simulate some time passing
        try { Thread.sleep(10); } catch (InterruptedException ignored) {}
        stopWatch.split();
        stopWatch.stop(); // This sets stopTime to a value > -1

        // Verify stopTime is not -1 (internal state check via logic)
        // Since stopTime is private, we verify that unsplit() completes without error
        // and subsequent state checks pass.
        stopWatch.unsplit();

        // If we can call split/stop again, it implies the internal state is valid
        // and the method executed its logic (setting stopTime = -1 and state = UNSPLIT)
        stopWatch.start();
        stopWatch.split();
        // If unsplit didn't work correctly, the internal state might be corrupted
        stopWatch.unsplit(); 
    }
}
